BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT jsonb_build_object(
'captured_at',to_char(transaction_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
'transaction_read_only',current_setting('transaction_read_only'),
'project','slzglmtiyrzygpkiuthf',
'products',(SELECT jsonb_agg(jsonb_build_object('product_id',id,'name',nombre,'state',estado,'sku_base',sku_base,'has_variants',tiene_variantes,'catalog_version',catalog_version,'category_id',categoria_id,'brand_id',marca_id) ORDER BY id) FROM catalog.products),
'skus',(SELECT jsonb_agg(jsonb_build_object('variant_id',id,'product_id',product_id,'sku',sku,'state',estado,'catalog_version',catalog_version) ORDER BY sku) FROM catalog.variants),
'prices',(SELECT jsonb_agg(jsonb_build_object('price_id',p.id,'validity_id',v.id,'product_id',p.product_id,'sku',p.sku,'channel_id',p.channel_id,'amount',v.precio_regular::text,'offer_amount',v.precio_oferta::text,'currency',v.currency,'price_version',v.price_version,'valid_from',to_char(v.valid_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'valid_until',CASE WHEN v.valid_until IS NULL THEN null ELSE to_char(v.valid_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,'is_cancelled',v.is_cancelled) ORDER BY p.id,v.id) FROM pricing.prices p JOIN pricing.price_validities v ON v.price_id=p.id),
'inventory',(SELECT jsonb_agg(jsonb_build_object('sku',sku,'registered_locations',registered_locations,'positive_available_location',positive_available_location) ORDER BY sku) FROM (SELECT sku_id AS sku,count(*) AS registered_locations,bool_or(available>0) AS positive_available_location FROM inventory.stock_balance GROUP BY sku_id) s),
'categories',(SELECT jsonb_agg(jsonb_build_object('id',id,'name',nombre,'state',estado,'taxonomy_version',taxonomy_version) ORDER BY id) FROM taxonomy.categories),
'brands',(SELECT jsonb_agg(jsonb_build_object('id',id,'name',nombre,'state',estado,'taxonomy_version',taxonomy_version) ORDER BY id) FROM taxonomy.brands),
'seed_privileges',(SELECT jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'select',has_table_privilege('po_promotions_seed',c.oid,'SELECT'),'insert',has_table_privilege('po_promotions_seed',c.oid,'INSERT'),'update_any_column',has_any_column_privilege('po_promotions_seed',c.oid,'UPDATE')) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='promotions' AND c.relname IN ('promotions','promotion_scopes','combination_policy','coupons','recommendation_rules','recommendation_items')),
'locking_functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'security_definer',p.prosecdef,'definition_md5',md5(pg_get_functiondef(p.oid)),'contains_for_update',pg_get_functiondef(p.oid) ILIKE '%FOR UPDATE%') ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='promotions' AND p.proname IN ('fn_lock_parent','fn_guard_coupon')),
'promotions_counts',jsonb_build_object('promotions',(SELECT count(*) FROM promotions.promotions),'promotion_scopes',(SELECT count(*) FROM promotions.promotion_scopes),'combination_policy',(SELECT count(*) FROM promotions.combination_policy),'coupons',(SELECT count(*) FROM promotions.coupons),'recommendation_rules',(SELECT count(*) FROM promotions.recommendation_rules),'recommendation_items',(SELECT count(*) FROM promotions.recommendation_items))
) AS snapshot;
ROLLBACK;
